    output reg signed [7:0] weight
);
    always @(*) begin
        case (ch)
            3'd0: begin delay = 6'd14; weight = 8'sd15 ; end
            3'd1: begin delay = 6'd11; weight = 8'sd52 ; end
            3'd2: begin delay = 6'd9 ; weight = 8'sd95 ; end
            3'd3: begin delay = 6'd8 ; weight = 8'sd123; end
            3'd4: begin delay = 6'd8 ; weight = 8'sd123; end
            3'd5: begin delay = 6'd9 ; weight = 8'sd95 ; end
            3'd6: begin delay = 6'd11; weight = 8'sd52 ; end
            3'd7: begin delay = 6'd14; weight = 8'sd15 ; end
            default: begin delay = 6'd0; weight = 8'sd0; end
        endcase
    end
endmodule
